{"code":"def transform(grid):
    a=[r[:] for r in grid]
    pts=[(r,c) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]==5]
    # source is the marker adjacent to the patterned colored object; generally first marker
    s=pts[0]
    # identify marker with nearby nonzero cells, otherwise first
    for p in pts:
        near=False
        for r in range(max(0,p[0]-2),min(len(a),p[0]+3)):
            for c in range(max(0,p[1]-2),min(len(a[0],p[0]+3))):
                if a[r][c] not in (0,5): near=True
        if near: s=p; break
    t=pts[1] if pts[0]==s else pts[0]
    dr,dc=t[0]-s[0],t[1]-s[1]
    # erase destination marker
    a[t[0]][t[1]]=0
    original=[row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if original[r][c] not in (0,5):
                rr,cc=r+dr,c+dc
                if 0<=rr<len(a) and 0<=cc<len(a[0]): a[rr][cc]=original[r][c]
    return a"}

